with.script:
// GitHub Actions billing API (requires token with read:org or billing scope)
// Falls back to workflow count summary if billing scope unavailable
const SOFT_LIMIT_MINUTES = 1600;
const HARD_LIMIT_MINUTES = 2000;

let usedMinutes = null;
let billingAvailable = false;

try {
  // Attempt to call billing API — requires GITHUB_TOKEN with billing:read scope
  const billingResp = await github.rest.billing.getGithubActionsBillingOrg({
    org: context.repo.owner,
  });

  if (billingResp?.data) {
    usedMinutes = billingResp.data.total_minutes_used;
    billingAvailable = true;
  }
} catch (err) {
  const status = err?.status ?? err?.response?.status;
  if (status === 403 || status === 404) {
    // Billing API not available for this token scope or plan — expected fallback
    core.info(`Billing API unavailable (HTTP ${status}) — falling back to manual tracking guidance.`);
  } else {
    // Transient or unexpected error — surface it so it is visible
    core.warning(`Billing API call failed unexpectedly: ${err?.message ?? err}`);
  }
}

const date = '${{ needs.collect-metrics.outputs.report_date }}';
const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

let summaryLines = [
  '## 💳 GitHub Actions Billing Check',
  '',
  `**Date:** ${date}`,
  `**Run:** ${runUrl}`,
  '',
];

if (billingAvailable && usedMinutes !== null) {
  const pct = Math.round((usedMinutes / HARD_LIMIT_MINUTES) * 100);
  const status = usedMinutes >= HARD_LIMIT_MINUTES ? '🔴 OVER LIMIT'
               : usedMinutes >= SOFT_LIMIT_MINUTES  ? '🟡 NEAR LIMIT (80%+)'
               : '🟢 OK';

  summaryLines = summaryLines.concat([
    `| Metric | Value |`,
    `|--------|-------|`,
    `| Minutes used | ${usedMinutes} / ${HARD_LIMIT_MINUTES} (${pct}%) |`,
    `| Status | ${status} |`,
    '',
  ]);

  if (usedMinutes >= SOFT_LIMIT_MINUTES) {
    core.warning(`GitHub Actions minutes at ${pct}% of free tier limit (${usedMinutes}/${HARD_LIMIT_MINUTES}). Review docs/BILLING-TRACKING.md.`);
  }
} else {
  summaryLines = summaryLines.concat([
    '> ℹ️ Billing API not available for this token scope.',
    '> Monitor usage manually at: https://github.com/settings/billing',
    '> See `docs/BILLING-TRACKING.md` for cost thresholds and optimization tips.',
    '',
  ]);
}

summaryLines = summaryLines.concat([
  '### Vercel Usage',
  '',
  '> Monitor Vercel usage at: https://vercel.com/account/usage',
  '> See `docs/BILLING-TRACKING.md` for Vercel thresholds.',
  '',
  '### Optimization Checklist',
  '',
  '- [ ] All workflows have `paths:` filters (no unnecessary runs)',
  '- [ ] All workflows have `concurrency:` groups configured',
  '- [ ] Artifacts use `retention-days: 7`',
  '- [ ] Vercel `regions: ["fra1"]` set in vercel.json',
  '- [ ] `outputFileTracingExcludes` configured in next.config.ts',
  '',
  '---',
  '_Generated by analytics-bot billing-check · AI-IQ-SUPER-PLATFORMA_',
]);

// Write to step summary
const { appendFileSync } = await import('fs');
appendFileSync(process.env.GITHUB_STEP_SUMMARY, summaryLines.join('\n'));

