const { data: labels } = await github.rest.issues.listLabelsForRepo({
  owner: context.repo.owner,
  repo: context.repo.repo,
});
const labelExists = labels.some(l => l.name === 'engine:needs-registration');
if (!labelExists) {
  await github.rest.issues.createLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    name: 'engine:needs-registration',
    color: 'e4e669',
    description: 'Engine wrapper postoji ali nije registrovan u engine-registry-all.ts',
  });
}
await github.rest.issues.addLabels({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  labels: ['engine:needs-registration'],
});

const { data: labels } = await github.rest.issues.listLabelsForRepo({
  owner: context.repo.owner,
  repo: context.repo.repo,
});
const labelExists = labels.some(l => l.name === 'engine:registered');
if (!labelExists) {
  await github.rest.issues.createLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    name: 'engine:registered',
    color: '0e8a16',
    description: 'Svi engine wrapper-i su registrovani u engine-registry-all.ts',
  });
}
// Try to remove the needs-registration label if it exists
try {
  await github.rest.issues.removeLabel({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    name: 'engine:needs-registration',
  });
} catch (e) {
  // Label might not exist on this PR, ignore
}
await github.rest.issues.addLabels({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  labels: ['engine:registered'],
});

