node <<'NODE'
const fs = require('fs');

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

const doc = fs.readFileSync('docs/EXTRIMLI-EXTERNAL-GITHUB.md', 'utf8');
const developerCreateProgramDoc = fs.readFileSync('docs/EXTRIMLI-DEVELOPER-CREATE-PROGRAM.md', 'utf8');
const links = fs.readFileSync('docs/MULTI-REPO-LINKS.md', 'utf8');
const extrimli = fs.readFileSync('docs/EXTRIMLI.md', 'utf8');
const worldBankDoc = fs.readFileSync('docs/AI-IQ-WORLD-BANK-AI-IDENTITY-FINANCE-GOVERNANCE.md', 'utf8');
const developerCreateContract = fs.readFileSync('src/lib/extrimli/developer-create-vrh-ekviladenta-contract.ts', 'utf8');
const config = JSON.parse(fs.readFileSync('.agent-config.json', 'utf8'));
const agent = config.agents['extrimli-validator-agent'];

assert(doc.includes('extrimli:external-github'), 'canonical doc must declare extrimli:external-github label');
assert(doc.includes('spaja86/IO-OPENUI-AO'), 'canonical doc must declare downstream repo');
assert(doc.includes('.github/workflows/extrimli-external-github.yml'), 'canonical doc must reference governance workflow');
assert(doc.includes('.github/workflows/extrimli-governance-conformance.yml'), 'canonical doc must reference governance conformance workflow');
assert(doc.includes('WAWE 1') && doc.includes('WAWE 5'), 'canonical doc must define WAWE 1-5 rollout phases');
assert(doc.includes('Promotion freeze'), 'canonical doc must define promotion freeze guard');
assert(doc.includes('docs/EXTRIMLI.md') && doc.includes('docs/MULTI-REPO-LINKS.md'), 'canonical doc must lock source-of-truth docs');
assert(doc.includes('DEVELOPER AND CREATE / VRH PROGRAMSKOG EKVILADENTA / AI PLATE'), 'canonical doc must declare AI PLATE enterprise package');
assert(doc.includes('12.000 EUR') && doc.includes('premium-rollout-regime'), 'canonical doc must lock weekly AI PLATE pricing governance');
assert(doc.includes('paymentCycle=monthly-or-annual'), 'canonical doc must preserve the enterprise master billing lock');
assert(developerCreateProgramDoc.includes('docs + types + routes + tests + workflows'), 'Developer/Create program doc must lock docs/types/routes/tests/workflows');
assert(developerCreateProgramDoc.includes('roadmapStageId=Verzija 7') && developerCreateProgramDoc.includes('premium-rollout-regime'), 'Developer/Create program doc must lock V7 AI PLATE execution and pricing governance');
assert(developerCreateProgramDoc.includes('src/tests/lib/extrimli-extrem.test.ts') && developerCreateProgramDoc.includes('src/tests/lib/extrimli-extrondol.test.ts'), 'Developer/Create program doc must lock EXTREM/EXTRONDOL tests');
assert(developerCreateProgramDoc.includes('DOK + DIK + FOR') && developerCreateProgramDoc.includes('DOK/DIK/DAK/DUK/FOR'), 'Developer/Create program doc must include FOR in the ownership and consistency lock');
assert(developerCreateProgramDoc.includes('AI IQ WORLD BANK PREPISKA') && developerCreateProgramDoc.includes('documentation-only governance evidence'), 'Developer/Create program doc must lock AI IQ WORLD BANK prepiska as documentation-only governance evidence');
assert(developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA == KRALJEVSKI PROGRAMSKI UNEVERZITET'), 'Developer/Create program doc must lock the unified KRALJEVSKI programmatic narrative');
assert(developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA == MAPA UMA') && developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA == ŽIVOPIS U DIGITALIZMU'), 'Developer/Create program doc must lock MAPA UMA and ŽIVOPIS U DIGITALIZMU additive aliases');
assert(developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA == DIJALIZA POGONSKOG OMOTAČA'), 'Developer/Create program doc must lock DIJALIZA POGONSKOG OMOTAČA additive alias');
assert(developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA == NOTES 1450') && developerCreateProgramDoc.includes('bounded radni-handoff paket'), 'Developer/Create program doc must lock NOTES 1450 bounded work continuation package');
assert(developerCreateProgramDoc.includes('DEVELOPER AND CREATE == VRH PROGRAMSKOG EKVILADENTA') && developerCreateProgramDoc.includes('Kompanija SPAJA / Digitalna Industrija'), 'Developer/Create program doc must lock canonical scope and enterprise mapping');
assert(developerCreateContract.includes('DEVELOPER_CREATE_VRH_DIJALIZA_POGONSKOG_OMOTACA_ALIAS') && developerCreateContract.includes('DEVELOPER_CREATE_VRH_MAPA_UMA_ALIAS') && developerCreateContract.includes('DEVELOPER_CREATE_VRH_ZIVOPIS_U_DIGITALIZMU_ALIAS') && developerCreateContract.includes('dokDikFor'), 'Developer/Create contract must retain additive alias ownership boundaries');
assert(developerCreateContract.includes('DEVELOPER_CREATE_VRH_DIJALIZA_POGONSKOG_OMOTACA_ALIAS') && developerCreateContract.includes('dokDikFor'), 'Developer/Create contract must retain DIJALIZA alias ownership boundary');
assert(developerCreateContract.includes('DEVELOPER_CREATE_NOTES_1450_CANONICAL_ALIAS') && developerCreateContract.includes('DEVELOPER_CREATE_NOTES_1450_BOUNDED_SIGNALS'), 'Developer/Create contract must retain NOTES 1450 bounded signal contract');
assert(links.includes('Developer/Create four-track package + `Kompanija SPAJA / Digitalna Industrija` enterprise summary') && links.includes('summary-safe fields'), 'multi-repo links must define the four-track and enterprise summary downstream boundary');
assert(developerCreateProgramDoc.includes('BEZPOVRATNE SUBVENCIJE') && developerCreateProgramDoc.includes('approval') && developerCreateProgramDoc.includes('payment-verification') && developerCreateProgramDoc.includes('payout-readiness'), 'Developer/Create program doc must lock bezpovratne subvencije governance-only evidence');
assert(doc.includes('EXTRIMLI_EXTENDOL_CONTRACT_VERSION'), 'canonical doc must declare EXTRIMLI Extendol contract');
assert(doc.includes('/api/extrimli/extendol'), 'canonical doc must reference EXTRIMLI Extendol unified endpoint');
assert(doc.includes('/api/extrimli/koron'), 'canonical doc must reference EXTRIMLI KORON endpoint');
assert(doc.includes('/api/extrimli/extrondend') && doc.includes('/api/extrimli/extrondol'), 'canonical doc must reference EXTRONDEND and EXTRONDOL endpoints');
assert(doc.includes('nivo-duet:logic-change') && doc.includes('dinkos:logic-change'), 'canonical doc must declare NIVO DUET and DINKOS labels');
assert(doc.includes('/api/duet/evaluate'), 'canonical doc must reference DUET source signal');
assert(links.includes('EXTRIMLI — External GitHub Surface'), 'multi-repo links must contain external GitHub section');
assert(links.includes('EXTRIMLI KORON overlay surface'), 'multi-repo links must contain KORON surface section');
assert(links.includes('EXTRIMLI EXTRONDEND aggregation surface') && links.includes('EXTRIMLI EXTRONDOL orchestration surface'), 'multi-repo links must include EXTRONDEND/EXTRONDOL sections');
assert(links.includes('EXTRIMLI NIVO DUET / DINKOS signal contract'), 'multi-repo links must include NIVO DUET / DINKOS section');
assert(links.includes('EXTRIMLI EXTEMEL/EXTREMOL WAWE map'), 'multi-repo links must include EXTRIMLI WAWE map');
assert(links.includes('EXTRIMLI governance conformance audit'), 'multi-repo links must include governance conformance section');
assert(links.includes('AI PLATE enterprise package') && links.includes('audit-safe snapshot'), 'multi-repo links must define AI PLATE downstream audit-safe sync');
assert(links.includes('AI IQ WORLD BANK prepiska') && links.includes('never sync real bank records'), 'multi-repo links must keep AI IQ WORLD BANK prepiska audit-safe only');
assert(links.includes('BEZPOVRATNE SUBVENCIJE') && links.includes('operational credentials'), 'multi-repo links must include bezpovratne subvencije governance sync boundary');
assert(links.includes('IO-OPENUI-AO#<follow-up issue> -> AI-IQ-SUPER-PLATFORMA#EXTRIMLI-EXTERNAL-GITHUB'), 'multi-repo links must include bidirectional audit convention');
