const pr = context.payload.pull_request;
const body = pr.body || "";
const labels = (pr.labels || []).map((l) => l.name.toLowerCase());

let automationTouched = false;
let crossRepoTouched = false;
const isAutomationFile = (f) =>
  f.startsWith(".github/workflows/") ||
  f.startsWith(".github/actions/") ||
  f === ".agent-config.json" ||
  f === "vercel.json" ||
  f === "package.json" ||
  f === "next.config.ts" ||
  f === "tsconfig.json";
const isCrossRepoFile = (f) =>
  f === "docs/MULTI-REPO-LINKS.md" ||
  f.startsWith("platforms/io-openui-ao/") ||
  f.startsWith("platforms/nova-generacija/");
const riskyLabels = new Set([
  "security:needs-review",
  "security:review-needed",
  "nova-generacija",
  "nova-generacija:review",
  "race:fairness-review",
  "calculator:logic-change",
  "agent:config-change"
]);

let page = 1;
while (true) {
  const { data } = await github.rest.pulls.listFiles({
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: pr.number,
    per_page: 100,
    page
  });

  if (!data.length) break;
  if (data.some((f) => isAutomationFile(f.filename))) automationTouched = true;
  if (data.some((f) => isCrossRepoFile(f.filename))) crossRepoTouched = true;
  page += 1;
}

const riskyLabelTouched = labels.some((l) => riskyLabels.has(l));
const requiresOkrid = automationTouched || crossRepoTouched || riskyLabelTouched;

const requiredPatterns = [
  /cost impact/i,
  /rollback plan/i,
  /kpi impact/i,
  /cost center\s*\/\s*owner/i
];

const missingGovernance = requiredPatterns
  .filter((pattern) => !pattern.test(body))
  .map((pattern) => pattern.toString());
if (automationTouched && missingGovernance.length) {
  core.setFailed(
    "Automation/config PRs must include cost governance fields in PR body. Missing: " +
    missingGovernance.join(", ")
  );
  return;
}

if (requiresOkrid) {
  const okridPatterns = [
    /okrid\s*id\s*:/i,
    /okrid-\d{4}-[a-z0-9-]+-\d{3}/i,
    /scope\s*\(?.*objective.*initiative.*release-governance.*\)?\s*:/i,
    /owner\s*:/i,
    /roadmap item\s*:/i,
    /kpi status\s*:/i
  ];

  const missingOkrid = okridPatterns
    .filter((pattern) => !pattern.test(body))
    .map((pattern) => pattern.toString());

  if (missingOkrid.length) {
    core.setFailed(
      "This PR requires OKRID linkage. Missing OKRID fields in PR body: " +
      missingOkrid.join(", ")
    );
    return;
  }
}

if (!automationTouched && !requiresOkrid) {
  core.info("No automation/config or OKRID-mandatory changes detected; governance gate skipped.");
  return;
}

core.info("Governance and OKRID checks passed.");

